import React, { useEffect, useMemo, useRef, useState } from "react";
import {
  AccessibilityInfo,
  PanResponder,
  StyleSheet,
  View,
  type ViewStyle,
} from "react-native";
import {
  Canvas,
  Group,
  ImageShader,
  Skia,
  Vertices,
  type SkImage,
} from "@shopify/react-native-skia";
import {
  cancelAnimation,
  runOnJS,
  useDerivedValue,
  useSharedValue,
  withSpring,
  type SharedValue,
} from "react-native-reanimated";
import {
  PANELS,
  atlasUV,
  foldMesh,
  makeFoldGrid,
  releaseTarget,
  scrub,
  type FoldMesh,
  type Point,
} from "./foldMath";

export type FoldedPassProps = {
  /** Frozen paper: fronts in the left half, backs in the right half, three panels stacked top to bottom. */
  atlas: SkImage;
  /** Width of the pass and height of ONE panel, in layout points. The component is width x (3 * panelHeight). */
  width: number;
  panelHeight: number;
  expanded: boolean;
  onExpandedChange: (expanded: boolean) => void;
  /** The real, live content at rest, laid out at width x (3 * panelHeight). Hidden while the paper moves. */
  children?: React.ReactNode;
  slowMotion?: boolean;
  reducedMotion?: boolean;
  style?: ViewStyle;
};

const PAD = 18;

// One-pixel-tall lookup strip: the pixel at x is black with alpha (1 - x / 255). The shading pass maps each vertex's
// shade into this strip as a texture coordinate, so the GPU interpolates shade across the triangle and the strip turns
// it into a darkening overlay. (Per-vertex colors are not used: they do not combine with an image shader on web.)
function makeRamp() {
  const surface = Skia.Surface.MakeOffscreen(256, 1);
  if (!surface) throw new Error("Unable to prepare the shading ramp");
  const canvas = surface.getCanvas(),
    paint = Skia.Paint();
  canvas.clear(Skia.Color("transparent"));
  for (let i = 0; i < 256; i++) {
    paint.setColor(Skia.Color(`rgba(0,0,0,${(1 - i / 255).toFixed(4)})`));
    canvas.drawRect(Skia.XYWHRect(i, 0, 1, 1), paint);
  }
  surface.flush();
  const snapshot = surface.makeImageSnapshot(),
    copy = snapshot.makeNonTextureImage();
  snapshot.dispose();
  surface.dispose();
  paint.dispose();
  if (!copy) throw new Error("Unable to copy the shading ramp");
  return copy;
}

function Panel({
  index,
  mesh,
  uv,
  indices,
  atlas,
  ramp,
}: {
  index: number;
  mesh: SharedValue<FoldMesh>;
  uv: Point[];
  indices: number[];
  atlas: SkImage;
  ramp: SkImage;
}) {
  const aw = atlas.width(),
    ah = atlas.height();
  const vertices = useDerivedValue(() => mesh.value.panels[index].pos);
  const textures = useDerivedValue(() => atlasUV(index, mesh.value.panels[index].front, uv, aw, ah));
  const shadeTextures = useDerivedValue(() =>
    mesh.value.panels[index].shade.map((s) => ({ x: Math.max(0.5, Math.min(255.5, s * 255 + 0.5)), y: 0.5 })),
  );
  return (
    <>
      <Vertices vertices={vertices} textures={textures} indices={indices} mode="triangles">
        <ImageShader image={atlas} tx="clamp" ty="clamp" />
      </Vertices>
      <Vertices vertices={vertices} textures={shadeTextures} indices={indices} mode="triangles">
        <ImageShader image={ramp} tx="clamp" ty="clamp" />
      </Vertices>
    </>
  );
}

export function FoldedPass({
  atlas,
  width,
  panelHeight,
  expanded,
  onExpandedChange,
  children,
  slowMotion = false,
  reducedMotion,
  style,
}: FoldedPassProps) {
  const total = panelHeight * PANELS;
  const progress = useSharedValue(expanded ? 1 : 0);
  const [systemReduce, setSystemReduce] = useState(false);
  const reduce = !!reducedMotion || systemReduce;
  const [moving, setMoving] = useState(false);
  const [open, setOpen] = useState(expanded);
  const grid = useMemo(() => makeFoldGrid(), []);
  const ramp = useMemo(() => makeRamp(), []);
  useEffect(() => () => ramp.dispose(), [ramp]);
  const mounted = useRef(true),
    dragging = useRef(false),
    movingRef = useRef(false),
    destination = useRef(expanded),
    revision = useRef(0),
    start = useRef(0);
  const latest = useRef({ slowMotion, reduce, onExpandedChange, panelHeight });
  latest.current = { slowMotion, reduce, onExpandedChange, panelHeight };

  useEffect(() => {
    mounted.current = true;
    AccessibilityInfo.isReduceMotionEnabled()
      .then((v) => mounted.current && setSystemReduce(v))
      .catch(() => {});
    const sub = AccessibilityInfo.addEventListener("reduceMotionChanged", setSystemReduce);
    return () => {
      mounted.current = false;
      revision.current++;
      sub.remove();
      cancelAnimation(progress);
    };
  }, [progress]);

  const finish = (value: boolean, generation: number) => {
    if (!mounted.current || generation !== revision.current) return;
    movingRef.current = false;
    setOpen(value);
    setMoving(false);
  };
  const setMotion = (value: boolean) => {
    movingRef.current = value;
    setMoving(value);
  };
  // Spring toward an end. A slow-motion spring is the same spring stretched four times in time.
  const settle = (to: boolean, velocity = 0) => {
    const generation = ++revision.current;
    destination.current = to;
    cancelAnimation(progress);
    const end = to ? 1 : 0;
    if (latest.current.reduce) {
      progress.value = end;
      finish(to, generation);
      return;
    }
    const k = latest.current.slowMotion ? 4 : 1;
    setMotion(true);
    progress.value = withSpring(
      end,
      {
        damping: 17 / k,
        stiffness: 170 / (k * k),
        mass: 1,
        velocity: velocity / k,
        overshootClamping: false,
        energyThreshold: 1e-5,
      },
      (done) => {
        if (done) runOnJS(finish)(to, generation);
      },
    );
  };
  // Controlled prop: reverse from wherever the paper is.
  useEffect(() => {
    if (destination.current !== expanded) settle(expanded);
    else if (!movingRef.current) setOpen(expanded);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [expanded]);
  // Changing speed or Reduce Motion mid-flight restarts the spring toward the same end.
  useEffect(() => {
    if (movingRef.current && !dragging.current) settle(destination.current);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [slowMotion, reduce]);

  const responder = useMemo(
    () =>
      PanResponder.create({
        // At rest the live children keep their own touches; a vertical drag takes over. Mid-motion, any touch grabs the paper.
        onStartShouldSetPanResponder: () => movingRef.current,
        onMoveShouldSetPanResponderCapture: (_, g) =>
          !latest.current.reduce && Math.abs(g.dy) > 8 && Math.abs(g.dy) > Math.abs(g.dx) * 1.2,
        onPanResponderGrant: () => {
          revision.current++;
          cancelAnimation(progress);
          dragging.current = true;
          start.current = progress.value;
          setMotion(true);
        },
        onPanResponderMove: (_, g) => {
          if (!dragging.current) return;
          progress.value = scrub(start.current, g.dy, latest.current.panelHeight * 2.4);
        },
        onPanResponderRelease: (_, g) => {
          if (!dragging.current) return;
          dragging.current = false;
          const next = Math.abs(g.dy) < 4 ? !destination.current : releaseTarget(progress.value, g.vy);
          // Hand the finger's speed to the spring so release feels continuous (u per second).
          const speed = (g.vy * 1000) / (latest.current.panelHeight * 2.4);
          settle(next, Math.abs(g.dy) < 4 ? 0 : speed);
          latest.current.onExpandedChange(next);
        },
        onPanResponderTerminate: () => {
          if (!dragging.current) return;
          dragging.current = false;
          settle(destination.current);
        },
        onPanResponderTerminationRequest: () => false,
      }),
    [progress],
  );

  const mesh = useDerivedValue(() => foldMesh(progress.value, width, panelHeight));
  if (width <= 0 || panelHeight <= 0) return null;
  const restHeight = open ? total : panelHeight;
  return (
    <View style={[{ width, height: total }, style]} {...responder.panHandlers}>
      <View
        style={{ width, height: restHeight, overflow: "hidden", opacity: moving ? 0 : 1 }}
        pointerEvents={moving ? "none" : "auto"}
        accessibilityElementsHidden={moving}
        importantForAccessibility={moving ? "no-hide-descendants" : "auto"}
      >
        {children}
      </View>
      {!reduce ? (
        <Canvas
          pointerEvents="none"
          style={{ position: "absolute", left: -PAD, top: -PAD, width: width + PAD * 2, height: total + PAD * 2, opacity: moving ? 1 : 0 }}
        >
          <Group transform={[{ translateX: PAD }, { translateY: PAD }]}>
            <Panel index={2} mesh={mesh} uv={grid.uv} indices={grid.indices} atlas={atlas} ramp={ramp} />
            <Panel index={1} mesh={mesh} uv={grid.uv} indices={grid.indices} atlas={atlas} ramp={ramp} />
            <Panel index={0} mesh={mesh} uv={grid.uv} indices={grid.indices} atlas={atlas} ramp={ramp} />
          </Group>
        </Canvas>
      ) : null}
    </View>
  );
}

// Folded Pass geometry. Three panels joined by two creases (a Z-fold), seen through a perspective camera.
// Pure functions shared by the React Native Skia component and the web preview, so both draw the same mesh.
export type Point = { x: number; y: number };
export type PanelMesh = { pos: Point[]; shade: number[]; front: boolean };
export type FoldMesh = { panels: PanelMesh[] };

export const PANELS = 3;
export const COLS = 4;
// Row stops along a panel (0 = start crease, 1 = end crease). Dense near the creases so crease shading has resolution.
export const ROW_STOPS = [0, 0.025, 0.06, 0.11, 0.2, 0.35, 0.5, 0.65, 0.8, 0.89, 0.94, 0.975, 1];
export const ROWS = ROW_STOPS.length - 1;
export const VERTS = (COLS + 1) * (ROWS + 1);
// A fully folded pass stops a hair short of 180 degrees so the stack keeps a defined paper order.
export const PSI_MAX = Math.PI - 0.02;
const CAMERA = 560;
const YAW = 0.11;
const LIGHT = (() => {
  const l = [-0.32, -0.5, 0.8];
  const n = Math.hypot(l[0], l[1], l[2]);
  return [l[0] / n, l[1] / n, l[2] / n];
})();

export const clamp = (v: number, lo = 0, hi = 1) => {
  "worklet";
  return Math.max(lo, Math.min(hi, v));
};
const smooth = (v: number) => {
  "worklet";
  const t = clamp(v);
  return t * t * (3 - 2 * t);
};

export function makeFoldGrid() {
  const uv: Point[] = [],
    indices: number[] = [];
  for (let r = 0; r <= ROWS; r++) for (let c = 0; c <= COLS; c++) uv.push({ x: c / COLS, y: ROW_STOPS[r] });
  for (let r = 0; r < ROWS; r++)
    for (let c = 0; c < COLS; c++) {
      const a = r * (COLS + 1) + c,
        b = a + 1,
        d = a + COLS + 1,
        e = d + 1;
      indices.push(a, b, d, b, e, d);
    }
  return { uv, indices };
}

// Fold turn at each crease. u = 0 is folded, u = 1 is flat. A little overshoot past 1 is allowed (spring settle).
export function foldAngle(u: number) {
  "worklet";
  return clamp(1 - u, -0.05, 1) * PSI_MAX;
}

// Vertical drag distance that moves the pass from folded to open.
export function scrub(start: number, dy: number, distance: number) {
  "worklet";
  return clamp(start + dy / Math.max(1, distance), 0, 1);
}
export function releaseTarget(u: number, velocityY: number) {
  "worklet";
  return Math.abs(velocityY) > 0.3 ? velocityY > 0 : u >= 0.5;
}

// Paper position along panel 2 (the free panel between the creases). Its direction turns slowly along its
// length (a bow), so it bends like paper instead of staying a rigid plank.
function bowOf(psi: number) {
  "worklet";
  return 0.34 * Math.sin(psi);
}

export function foldMesh(u: number, width: number, panelHeight: number): FoldMesh {
  "worklet";
  const H = panelHeight,
    W = width,
    cx = W / 2;
  const uu = clamp(u, 0, 1.05);
  const psi = foldAngle(uu);
  const bow = bowOf(psi);
  const gamma = YAW * Math.sin(Math.PI * clamp(uu));
  const cg = Math.cos(gamma),
    sg = Math.sin(gamma);
  const vy = H * 3;
  const a0 = psi - bow / 2;
  const sinA0 = Math.sin(a0),
    cosA0 = Math.cos(a0);
  const k = (1 - Math.cos(psi)) / 2; // 0 flat, 1 fully folded
  const panels: PanelMesh[] = [];
  const yEnd2 = (() => {
    if (Math.abs(bow) < 1e-6) return H + H * Math.cos(psi);
    return H + (H * (Math.sin(psi + bow / 2) - sinA0)) / bow;
  })();
  const zEnd2 = (() => {
    if (Math.abs(bow) < 1e-6) return -H * Math.sin(psi);
    return (H * (Math.cos(psi + bow / 2) - cosA0)) / bow;
  })();
  for (let p = 0; p < PANELS; p++) {
    const pos: Point[] = [],
      shade: number[] = [];
    for (let r = 0; r <= ROWS; r++) {
      const s = ROW_STOPS[r];
      let y = 0,
        z = 0,
        alpha = 0;
      if (p === 0) {
        y = s * H;
      } else if (p === 1) {
        alpha = a0 + bow * s;
        if (Math.abs(bow) < 1e-6) {
          y = H + H * s * Math.cos(psi);
          z = -H * s * Math.sin(psi);
        } else {
          y = H + (H * (Math.sin(alpha) - sinA0)) / bow;
          z = (H * (Math.cos(alpha) - cosA0)) / bow;
        }
      } else {
        y = yEnd2 + s * H;
        z = zEnd2;
      }
      // Surface normal of the panel's front face before yaw.
      const ny = Math.sin(alpha),
        nzFlat = Math.cos(alpha);
      const nx = nzFlat * sg,
        nz = nzFlat * cg;
      let lit = (nx * LIGHT[0] + ny * LIGHT[1] + nz * LIGHT[2]) / LIGHT[2];
      for (let c = 0; c <= COLS; c++) {
        const x0 = (c / COLS) * W - cx;
        const xr = x0 * cg + z * sg,
          zr = -x0 * sg + z * cg;
        const scale = CAMERA / (CAMERA - zr);
        pos.push({ x: cx + xr * scale, y: vy + (y - vy) * scale });
        shade.push(lit); // temporary: lighting before facing and creases are known
      }
    }
    // Facing from the signed area of the projected panel outline (positive = front toward the viewer).
    const tl = pos[0],
      tr = pos[COLS],
      bl = pos[ROWS * (COLS + 1)],
      br = pos[ROWS * (COLS + 1) + COLS];
    const area =
      tl.x * tr.y - tr.x * tl.y + (tr.x * br.y - br.x * tr.y) + (br.x * bl.y - bl.x * br.y) + (bl.x * tl.y - tl.x * bl.y);
    const front = area >= 0;
    for (let r = 0; r <= ROWS; r++) {
      const s = ROW_STOPS[r];
      // Distances to the creases, in panel heights.
      const startCrease = p > 0, // panel 2 and 3 have a crease at their start
        endCrease = p < PANELS - 1; // panel 1 and 2 have one at their end
      // Crease 1 (between panels 1 and 2) is a ridge seen from the front; crease 2 is a valley from the front.
      const startKind = p === 1 ? (front ? 0.12 : 0.34) : p === 2 ? (front ? 0.34 : 0.12) : 0;
      const endKind = p === 0 ? (front ? 0.12 : 0.34) : p === 1 ? (front ? 0.34 : 0.12) : 0;
      let ao = 0;
      if (startCrease) ao += startKind * k * Math.pow(1 - smooth(s / 0.22), 1.6);
      if (endCrease) ao += endKind * k * Math.pow(1 - smooth((1 - s) / 0.22), 1.6);
      // Panel 3's top sits in the shadow of the panel above it while folded.
      if (p === 2) ao += 0.22 * k * Math.pow(1 - smooth(s / 0.9), 2);
      for (let c = 0; c <= COLS; c++) {
        const i = r * (COLS + 1) + c;
        let lit = shade[i];
        if (!front) lit = 2 - lit; // back face: light on the opposite side of the normal
        const base = 0.68 + 0.32 * clamp(lit, 0, 1);
        shade[i] = clamp(base * (1 - ao), 0.18, 1);
      }
    }
    panels.push({ pos, shade, front });
  }
  return { panels };
}

// Texture coordinates inside one atlas: fronts in the left half, backs in the right half, panels stacked top to bottom.
// Backs are mapped upside down because folding a panel over turns it about its crease.
export function atlasUV(panel: number, front: boolean, uv: Point[], atlasW: number, atlasH: number): Point[] {
  "worklet";
  const out: Point[] = [];
  for (let i = 0; i < uv.length; i++) {
    const u = uv[i].x,
      v = uv[i].y;
    const ax = front ? u * 0.5 : 0.5 + u * 0.5;
    const ay = (panel + (front ? v : 1 - v)) / PANELS;
    out.push({ x: ax * atlasW, y: ay * atlasH });
  }
  return out;
}

// The boarding pass used by the Example and the website preview, as plain data in panel-local points.
// One description is drawn by Skia, by Canvas 2D and by React Native views, so all three agree.
export const PASS_W = 292;
export const PASS_H = 112;
export type Corners = "all" | "top" | "bottom" | "none";
export type RectItem = { k: "rect"; x: number; y: number; w: number; h: number; color: string; r?: number; corners?: Corners };
export type TextItem = { k: "text"; x: number; y: number; size: number; color: string; text: string; align?: "left" | "center" | "right" };
export type Item = RectItem | TextItem;
export type PassDesign = { fronts: Item[][]; backs: Item[][]; check: { x: number; y: number; w: number; h: number } };

const INK = "#1f3a2c", GREEN = "#315843", TAN = "#ae8655", MUTED = "#63705f", PAPER = "#f3efe4", PAPER2 = "#f7f3e8";
const bars = (seed: number, x0: number, x1: number, y: number, h: number): RectItem[] => {
  const out: RectItem[] = [];
  let s = seed, x = x0;
  while (x < x1 - 3) {
    s = (s * 1103515245 + 12345) & 0x7fffffff;
    const w = 1 + (s >> 8) % 3, gap = 1 + (s >> 12) % 3;
    if (x + w > x1) break;
    out.push({ k: "rect", x, y, w, h, color: INK });
    x += w + gap;
  }
  return out;
};
const dashes = (y: number): RectItem[] => {
  const out: RectItem[] = [];
  for (let x = 14; x < PASS_W - 14; x += 10) out.push({ k: "rect", x, y, w: 5, h: 1, color: "#c9c2ae" });
  return out;
};

export function passDesign(checkedIn = false): PassDesign {
  const W = PASS_W, H = PASS_H;
  const check = { x: 200, y: 62, w: 76, h: 30 };
  const field = (x: number, y: number, label: string, value: string): Item[] => [
    { k: "text", x, y, size: 8, color: MUTED, text: label },
    { k: "text", x, y: y + 24, size: 20, color: INK, text: value },
  ];
  const fronts: Item[][] = [
    [
      { k: "rect", x: 0, y: 0, w: W, h: H, color: PAPER, r: 18, corners: "top" },
      { k: "rect", x: 0, y: 0, w: W, h: 26, color: GREEN, r: 18, corners: "top" },
      { k: "text", x: 16, y: 17, size: 9, color: "#f3efe4", text: "NATIVELET AIR" },
      { k: "text", x: W - 16, y: 17, size: 9, color: "#f3efe4", text: "BOARDING PASS", align: "right" },
      { k: "text", x: 16, y: 70, size: 38, color: INK, text: "BLR" },
      { k: "text", x: W - 16, y: 70, size: 38, color: INK, text: "LHR", align: "right" },
      { k: "rect", x: 104, y: 56, w: 84, h: 2, color: TAN },
      { k: "rect", x: 100, y: 54, w: 6, h: 6, color: TAN, r: 3 },
      { k: "rect", x: 186, y: 54, w: 6, h: 6, color: TAN, r: 3 },
      { k: "text", x: W / 2, y: 49, size: 10, color: GREEN, text: "NL 219", align: "center" },
      { k: "text", x: W / 2, y: 76, size: 10, color: MUTED, text: "10h 25m", align: "center" },
      { k: "text", x: 16, y: 100, size: 9, color: MUTED, text: "BENGALURU" },
      { k: "text", x: W - 16, y: 100, size: 9, color: MUTED, text: "LONDON HEATHROW", align: "right" },
    ],
    [
      { k: "rect", x: 0, y: 0, w: W, h: H, color: PAPER2, corners: "none" },
      ...dashes(0),
      ...field(16, 28, "PASSENGER", "S. Nandi"),
      ...field(150, 28, "GATE", "B12"),
      ...field(228, 28, "SEAT", "14A"),
      ...field(16, 78, "BOARDS", "21:40"),
      ...field(100, 78, "DEPARTS", "22:10"),
      { k: "rect", x: check.x, y: check.y, w: check.w, h: check.h, color: checkedIn ? TAN : GREEN, r: 15 },
      { k: "text", x: check.x + check.w / 2, y: check.y + 19, size: 11, color: "#f3efe4", text: checkedIn ? "Checked in" : "Check in", align: "center" },
      ...dashes(H - 1),
    ],
    [
      { k: "rect", x: 0, y: 0, w: W, h: H, color: PAPER, r: 18, corners: "bottom" },
      ...bars(7, 20, W - 20, 16, 54),
      { k: "text", x: W / 2, y: 90, size: 10, color: INK, text: "NL219 · BLR-LHR · 14A", align: "center" },
      { k: "text", x: W / 2, y: 103, size: 8, color: MUTED, text: "Hold to the scanner at the gate", align: "center" },
    ],
  ];
  const back = (corners: Corners): Item[] => [
    { k: "rect", x: 0, y: 0, w: W, h: H, color: "#e6ddc7", r: 18, corners },
    { k: "rect", x: 10, y: 10, w: W - 20, h: 1, color: "#cfc4a8" },
    { k: "rect", x: 10, y: H - 11, w: W - 20, h: 1, color: "#cfc4a8" },
    { k: "rect", x: 10, y: 10, w: 1, h: H - 20, color: "#cfc4a8" },
    { k: "rect", x: W - 11, y: 10, w: 1, h: H - 20, color: "#cfc4a8" },
    { k: "text", x: W / 2, y: H / 2 + 3, size: 9, color: "#a99b78", text: "NATIVELET AIR", align: "center" },
  ];
  return { fronts, backs: [back("top"), back("none"), back("bottom")], check };
}

import React, { useEffect, useMemo, useState } from "react";
import { Pressable, Text, View } from "react-native";
import { Skia, useTypeface, type SkFont, type SkTypeface } from "@shopify/react-native-skia";
import { FoldedPass } from "./FoldedPass";
import { PASS_H, PASS_W, passDesign, type Corners, type Item, type RectItem } from "./passDesign";

const GEIST = require("../text-morph/fonts/Geist-Regular.ttf");
const SCALE = 2;
const BOX_W = 340,
  BOX_H = 430,
  PASS_X = (BOX_W - PASS_W) / 2,
  PASS_Y = 28;
const radii = (it: RectItem): [number, number, number, number] => {
  const r = it.r ?? 0,
    c: Corners = it.corners ?? "all";
  return c === "all" ? [r, r, r, r] : c === "top" ? [r, r, 0, 0] : c === "bottom" ? [0, 0, r, r] : [0, 0, 0, 0];
};
const KAPPA = 0.5523;
function roundedPath(x: number, y: number, w: number, h: number, [tl, tr, br, bl]: number[]) {
  const p = Skia.PathBuilder.Make();
  p.moveTo(x + tl, y);
  p.lineTo(x + w - tr, y);
  p.cubicTo(x + w - tr + tr * KAPPA, y, x + w, y + tr - tr * KAPPA, x + w, y + tr);
  p.lineTo(x + w, y + h - br);
  p.cubicTo(x + w, y + h - br + br * KAPPA, x + w - br + br * KAPPA, y + h, x + w - br, y + h);
  p.lineTo(x + bl, y + h);
  p.cubicTo(x + bl - bl * KAPPA, y + h, x, y + h - bl + bl * KAPPA, x, y + h - bl);
  p.lineTo(x, y + tl);
  p.cubicTo(x, y + tl - tl * KAPPA, x + tl - tl * KAPPA, y, x + tl, y);
  p.close();
  return p.build();
}

// The paper: one atlas, fronts on the left and backs on the right, drawn once with Skia at 2x.
function drawAtlas(typeface: SkTypeface, checkedIn: boolean) {
  const design = passDesign(checkedIn);
  const surface = Skia.Surface.MakeOffscreen(PASS_W * SCALE * 2, PASS_H * SCALE * 3);
  if (!surface) throw new Error("Unable to prepare the pass texture");
  const canvas = surface.getCanvas(),
    paint = Skia.Paint();
  paint.setAntiAlias(true);
  canvas.clear(Skia.Color("transparent"));
  const fonts = new Map<string, SkFont>();
  const fontFor = (size: number) => {
    let f = fonts.get(String(size));
    if (!f) {
      f = Skia.Font(typeface, size * SCALE);
      fonts.set(String(size), f);
    }
    return f;
  };
  const drawItems = (items: Item[], ox: number, oy: number) => {
    for (const it of items) {
      paint.setColor(Skia.Color(it.color));
      if (it.k === "rect") {
        const [tl, tr, br, bl] = radii(it).map((v) => v * SCALE);
        if (tl + tr + br + bl === 0) canvas.drawRect(Skia.XYWHRect(ox + it.x * SCALE, oy + it.y * SCALE, it.w * SCALE, it.h * SCALE), paint);
        else canvas.drawPath(roundedPath(ox + it.x * SCALE, oy + it.y * SCALE, it.w * SCALE, it.h * SCALE, [tl, tr, br, bl]), paint);
      } else {
        const font = fontFor(it.size);
        const width = it.align === "left" || !it.align ? 0 : font.getTextWidth(it.text);
        const x = ox + it.x * SCALE - (it.align === "center" ? width / 2 : it.align === "right" ? width : 0);
        canvas.drawText(it.text, x, oy + it.y * SCALE, paint, font);
      }
    }
  };
  for (let p = 0; p < 3; p++) {
    drawItems(design.fronts[p], 0, p * PASS_H * SCALE);
    drawItems(design.backs[p], PASS_W * SCALE, p * PASS_H * SCALE);
  }
  surface.flush();
  const snapshot = surface.makeImageSnapshot(),
    copy = snapshot.makeNonTextureImage();
  snapshot.dispose();
  surface.dispose();
  paint.dispose();
  if (!copy) throw new Error("Unable to copy the pass texture");
  return copy;
}

// The same description rendered as real React Native views: live, selectable, pressable text at rest.
function RestItem({ it }: { it: Item }) {
  if (it.k === "rect") {
    const [tl, tr, br, bl] = radii(it);
    return (
      <View
        pointerEvents="none"
        style={{
          position: "absolute", left: it.x, top: it.y, width: it.w, height: it.h, backgroundColor: it.color,
          borderTopLeftRadius: tl, borderTopRightRadius: tr, borderBottomRightRadius: br, borderBottomLeftRadius: bl,
        }}
      />
    );
  }
  const box = 240;
  const left = it.align === "center" ? it.x - box / 2 : it.align === "right" ? it.x - box : it.x;
  return (
    <Text
      selectable={false}
      allowFontScaling={false}
      numberOfLines={1}
      style={{
        position: "absolute", left, top: it.y - it.size * 0.94, width: box, color: it.color, fontSize: it.size,
        lineHeight: Math.round(it.size * 1.2), userSelect: "none", textAlign: it.align ?? "left", includeFontPadding: false,
        fontFamily: "Geist-Regular",
        fontWeight: "400",
      }}
    >
      {it.text}
    </Text>
  );
}

export default function Example() {
  const [expanded, setExpanded] = useState(false),
    [slow, setSlow] = useState(false),
    [reduce, setReduce] = useState(false),
    [checkedIn, setCheckedIn] = useState(false);
  const typeface = useTypeface(GEIST);
  const atlas = useMemo(() => (typeface ? drawAtlas(typeface, checkedIn) : null), [typeface, checkedIn]);
  useEffect(() => () => atlas?.dispose(), [atlas]);
  const design = useMemo(() => passDesign(checkedIn), [checkedIn]);
  if (!atlas) return null;
  const chip = (on: boolean) => ({
    paddingVertical: 9, paddingHorizontal: 13, borderRadius: 24, borderWidth: 1,
    backgroundColor: on ? "#315843" : "#eeeade", borderColor: on ? "#315843" : "#c7caba",
  });
  return (
    <View style={{ alignItems: "center", gap: 10, paddingVertical: 14 }}>
      <View style={{ width: BOX_W, height: BOX_H, borderRadius: 18, backgroundColor: "#f4f1e9", overflow: "visible" }}>
        <FoldedPass
          style={{ position: "absolute", left: PASS_X, top: PASS_Y }}
          atlas={atlas}
          width={PASS_W}
          panelHeight={PASS_H}
          expanded={expanded}
          onExpandedChange={setExpanded}
          slowMotion={slow}
          reducedMotion={reduce}
        >
          <View style={{ width: PASS_W, height: PASS_H * 3 }}>
            {design.fronts.map((items, p) => (
              <View key={p} style={{ position: "absolute", left: 0, top: p * PASS_H, width: PASS_W, height: PASS_H }}>
                {items.map((it, i) => <RestItem key={i} it={it} />)}
              </View>
            ))}
            <Pressable
              accessibilityRole="button"
              accessibilityLabel={expanded ? "Fold pass" : "Open pass"}
              onPress={() => setExpanded((v) => !v)}
              style={{ position: "absolute", left: 0, top: 0, width: PASS_W, height: 52 }}
            />
            <Pressable
              accessibilityRole="button"
              accessibilityLabel={checkedIn ? "Checked in" : "Check in"}
              onPress={() => setCheckedIn(true)}
              style={{ position: "absolute", left: design.check.x, top: PASS_H + design.check.y, width: design.check.w, height: design.check.h }}
            />
          </View>
        </FoldedPass>
      </View>
      <Pressable
        accessibilityRole="button"
        onPress={() => setExpanded((v) => !v)}
        style={{ paddingVertical: 12, paddingHorizontal: 22, backgroundColor: "#315843", borderRadius: 24 }}
      >
        <Text style={{ color: "#fff", fontSize: 14, fontFamily: "Geist-Regular" }}>{expanded ? "Fold pass" : "Unfold pass"}</Text>
      </Pressable>
      <View style={{ flexDirection: "row", gap: 8 }}>
        <Pressable accessibilityRole="switch" accessibilityState={{ checked: slow }} onPress={() => setSlow((v) => !v)} style={chip(slow)}>
          <Text style={{ fontSize: 12, color: slow ? "#fff" : "#315843", fontFamily: "Geist-Regular" }}>Slow motion: {slow ? "on" : "off"}</Text>
        </Pressable>
        <Pressable accessibilityRole="switch" accessibilityState={{ checked: reduce }} onPress={() => setReduce((v) => !v)} style={chip(reduce)}>
          <Text style={{ fontSize: 12, color: reduce ? "#fff" : "#315843", fontFamily: "Geist-Regular" }}>Reduce motion: {reduce ? "on" : "off"}</Text>
        </Pressable>
      </View>
      <Text style={{ fontSize: 12, color: "#63705f", fontFamily: "Geist-Regular" }}>Drag the pass down to unfold it. Drag up to fold it.</Text>
    </View>
  );
}
